/**
 * <rf-social-proof> — Regional Finance Trustpilot social proof section.
 *
 * A pixel-faithful port of the section on
 * https://regionalfinance.com/borrow/debt-consolidation
 *
 * Usage:
 *   <script defer src="/rf-social-proof.js"></script>
 *   <rf-social-proof></rf-social-proof>
 *
 * Renders into a Shadow DOM: the host page's CSS cannot leak in, and this
 * component's CSS cannot leak out. Sizes itself in normal document flow —
 * no iframe, no height handshake.
 *
 * Every color, size, radius and font weight below is taken from the site's
 * design tokens (nextjs/src/styles/tokens.css). All px values are the rem
 * values x10, because the site sets html{font-size:62.5%} so 1rem = 10px.
 *
 * Attributes (all optional):
 *   endpoint    JSON feed URL (default: /api/trustpilot on the host origin)
 *   heading / body / note        Copy overrides
 *   cta-label / cta-href         CTA overrides ("" hides the button)
 *   cta-target                   Link target, e.g. "_blank" (default "_self")
 *   no-images                    Omit the three fanned portraits
 *   compact                      Portraits, heading and rating only (no review cards, note or button)
 *
 * Inline data (no fetch): put the feed JSON in a child
 *   <script type="application/json">…</script>
 * and the endpoint is ignored.
 *
 * Theming — set on the element or any ancestor; custom properties inherit
 * through the shadow boundary:
 *   --rf-font, --rf-blue, --rf-navy, --rf-text-dark, --rf-text-mid, --rf-text-light
 *
 * Expected feed payload:
 *   { trustScore: 4.5, profileUrl: "https://...", reviews: [ ...Trustpilot reviews ] }
 *
 * The Trustpilot API key is used only by the server half (see server/).
 */

/* Assets are inlined at build time so the component has no external
   dependencies: no CDN, no hotlinking, no CORS on any origin. */
const A = {
  leafL: "data:image/svg+xml;base64,",
  leafR: "data:image/svg+xml;base64,",
  tp: "data:image/svg+xml;base64,",
  portraits: [
    { src: "data:image/webp;base64,", alt: "portrait of young woman", cls: "left" },
    { src: "data:image/webp;base64,", alt: "portrait of man", cls: "center" },
    { src: "data:image/webp;base64,", alt: "portrait of woman", cls: "right" },
  ],
};

const DEFAULTS = {
  endpoint: "/api/trustpilot", // same-origin; override with the endpoint attribute
  heading: "Trusted by your neighbors",
  body:
    "For over 35 years, millions of customers have trusted us to provide the " +
    "simple, transparent, and straightforward financial support they deserve.",
  note: "Showing our 4 and 5 star Trustpilot reviews",
  ctaLabel: "See customer reviews",
  ctaHref: "https://regionalfinance.com/about-us/customer-reviews",
  ctaTarget: "_self",
};

const SLIDE_W = 320; // --slide-size on the site: 32rem
const GAP = 16;      // --slide-spacing: 1.6rem

const STYLES = `
:host {
  /* Design tokens, verbatim from tokens.css */
  --rf-font: "Plus Jakarta Sans", system-ui, -apple-system, sans-serif;
  --rf-blue: #2a71d4;          /* --brand-blue      */
  --rf-blue-hover: #1e4f95;    /* --hover-blue      */
  --rf-navy: #0d2240;          /* --brand-deep-blue */
  --rf-text-dark: #363636;     /* --high-emphasis-dark */
  --rf-text-mid: #595959;      /* --med-emphasis-dark  */
  --rf-text-light: #cdcdcd;    /* --med-emphasis-light */
  --rf-gray: #f2f2f2;          /* --surface-light-gray */
  --rf-gray-hover: #dedede;    /* --hover-gray         */
  display: block;
  font-family: var(--rf-font);
  background: #fff;
  container-type: inline-size;
}
:host([hidden]) { display: none; }
* { box-sizing: border-box; margin: 0; }

.wrap { display: flex; flex-direction: column; gap: 32px; padding-top: var(--rf-sp-top, 64px); overflow: hidden; }

/* ── Fanned portraits ───────────────────────────────────────────────── */
.portraits { position: relative; height: 208px; }
.portraits img {
  position: absolute; top: 50%; left: 50%;
  width: 140px; height: 177px; object-fit: cover;
  border: 4px solid #fff; border-radius: 16px;
  box-shadow: 0 3px 18px 0 rgba(0,0,0,.14);
  z-index: 1;
  transform: translate(-50%, -50%);
  transition: transform .8s cubic-bezier(.22,1,.36,1);
}
.portraits img.center { z-index: 2; }
/* Fan out when scrolled into view — mirrors the site's GSAP ScrollTrigger
   (start: "top 40%"; left x:-110 rot:-12, right x:110 rot:12). */
.portraits.open img.left  { transform: translate(-50%,-50%) translateX(-110px) rotate(-12deg); }
.portraits.open img.right { transform: translate(-50%,-50%) translateX(110px) rotate(12deg); }

/* ── Heading ────────────────────────────────────────────────────────── */
.head {
  align-self: center; text-align: center; display: flex; flex-direction: column;
  align-items: center; gap: 16px; padding: 0 24px; width: 100%; max-width: 754px;
  color: var(--rf-text-dark);
}
.head h2 { font-size: 48px; font-weight: 700; line-height: 1.2; }
.head p  { font-size: 18px; font-weight: 400; line-height: 1.4; color: var(--rf-text-mid); max-width: 562px; }

/* ── Rating row ─────────────────────────────────────────────────────── */
.rating { display: flex; align-items: center; justify-content: center; gap: 12px; overflow: hidden; }
.leaf { width: 39px; height: 59px; flex-shrink: 0; }
.score { font-size: 18px; font-weight: 700; line-height: 1.2; color: var(--rf-text-dark); white-space: nowrap; }
.score span { font-weight: 400; line-height: 1.4; }
.rating a { display: inline-flex; align-items: center; }
.tp { width: 104px; height: 26px; }

/* ── Carousel ───────────────────────────────────────────────────────── */
.carousel { display: flex; flex-direction: column; gap: 24px; overflow: hidden; }
.vp { overflow-x: auto; overflow-y: hidden; scroll-snap-type: x mandatory;
      scrollbar-width: none; -ms-overflow-style: none; padding-top: 64px; padding-bottom: 16px; }
.vp::-webkit-scrollbar { display: none; }
.track { display: flex; gap: ${GAP}px; }
/* Edge spacers instead of padding: trailing padding on a flex scroll
   container is not reliably scrollable, which left the last cards
   unreachable. Real flex items always are. Spacer + gap = 50% - half a
   card, so the first and last card can sit centred; never below 16px. */
.track::before, .track::after {
  content: ""; flex: 0 0 max(0px, calc(50% - ${SLIDE_W / 2 + GAP}px));
}
.slide { flex: 0 0 ${SLIDE_W}px; min-width: 0; scroll-snap-align: center;
         transform: translateY(calc(var(--o, 1) * -32px)); transition: transform .3s ease; }

/* ── Review card ────────────────────────────────────────────────────── */
.card { height: 460px; background: var(--rf-navy); border-radius: 48px; padding: 32px;
        display: flex; flex-direction: column; gap: 32px; }
.stars { display: flex; align-items: center; gap: 4px; color: #fff; }
.stars svg { width: 24px; height: 24px; flex-shrink: 0; }
.cbody { flex: 1; display: flex; flex-direction: column; justify-content: space-between; min-height: 0; }
.content { display: flex; flex-direction: column; gap: 8px; color: #fff; min-height: 0; }
.title { font-size: 24px; font-weight: 700; line-height: 1.2;
         display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; }
.text  { font-size: 16px; font-weight: 400; line-height: 1.4; color: var(--rf-text-light);
         display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 8; overflow: hidden; }
.who { display: flex; align-items: center; gap: 12px; color: #fff; min-width: 0; }
.who img { width: 56px; height: 56px; border-radius: 9999px; object-fit: cover; flex-shrink: 0; }
.init { width: 56px; height: 56px; border-radius: 9999px; flex-shrink: 0;
        display: flex; align-items: center; justify-content: center;
        font-size: 16px; font-weight: 700; line-height: 1.4;
        background: linear-gradient(14deg, #f4f7cf 0%, #bdf8ff 89.84%); color: var(--rf-navy); }
.name { font-size: 16px; font-weight: 500; line-height: 1.4;
        overflow: hidden; white-space: nowrap; text-overflow: ellipsis; min-width: 0; }

/* ── Controls (IconButton, variant="secondary", size="md") ──────────── */
.ctrls { display: flex; justify-content: center; align-items: center; gap: 8px; }
.ctrls button { all: unset; cursor: pointer; width: 48px; height: 48px; border-radius: 9999px;
                background: var(--rf-gray); display: flex; align-items: center; justify-content: center; }
.ctrls button:hover { background: var(--rf-gray-hover); }
.ctrls button:active { opacity: .85; transition: opacity .15s ease; }
.ctrls button:focus-visible { outline: 2px solid var(--rf-blue); outline-offset: 2px; }
.ctrls svg { width: 24px; height: 24px; color: var(--rf-text-dark); }

/* ── Disclaimer + CTA (Button, variant="primary", size="md") ────────── */
.note { font-size: 16px; font-weight: 400; line-height: 1.4; color: var(--rf-text-mid);
        align-self: center; text-align: center; }
.cta { display: flex; justify-content: center; align-items: center; }
.cta a { all: unset; cursor: pointer; box-sizing: border-box; display: inline-flex;
         align-items: center; justify-content: center; width: fit-content; height: 48px;
         padding: 0 24px; border-radius: 9999px; color: #fff; background: var(--rf-blue);
         font-size: 16px; font-weight: 500; line-height: 1.4; text-align: center; text-wrap: nowrap; }
.cta a:hover { background: var(--rf-blue-hover); }
.cta a:active { opacity: .85; transition: opacity .15s ease; }
.cta a:focus-visible { outline: 2px solid var(--rf-blue); outline-offset: 2px; }

/* The site drops --heading-lg to 36px below its desktop breakpoint. */
@container (max-width: 991px) { .head h2 { font-size: 36px; } }
@container (min-width: 992px) and (max-width: 1199px) { .head h2 { font-size: 42px; } }

@media (prefers-reduced-motion: reduce) {
  .slide, .portraits img { transition: none; }
}
`;

/* Icons lifted from the repo's SVG components so strokes match exactly. */
const STAR = `<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect width="100%" height="100%" rx="2.5" fill="currentColor" fill-opacity="0.12"/><path d="M19.5 10.3473L14.1784 9.79571L12 5L9.82151 9.79571L4.5 10.3473L8.47479 13.8633L7.36512 19L12 16.3765L16.6348 19L15.5252 13.8633L19.5 10.3473Z" fill="currentColor"/></svg>`;
const ARROW_L = `<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M20 12L4 12M10 18L4 12L10 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const ARROW_R = `<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12H20M14 6L20 12L14 18" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;

const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

const initials = (n) => {
  const p = String(n || "").trim().split(/\s+/);
  return p.length > 1 ? p.map((x) => x.charAt(0)).join("") : p[0].slice(0, 2);
};

class RfSocialProof extends HTMLElement {
  #root = this.attachShadow({ mode: "open" });
  #io = null;
  #ro = null;

  connectedCallback() { this.#load(); }

  disconnectedCallback() {
    this.#io?.disconnect();
    this.#ro?.disconnect();
  }

  #attr(name, fallback) {
    const v = this.getAttribute(name);
    return v === null ? fallback : v;
  }

  #show(data) {
    if (!data?.reviews?.length) { this.hidden = true; return; }
    this.#render(data);
    this.dispatchEvent(new CustomEvent("rf-load", { detail: data, bubbles: true }));
  }

  async #load() {
    // Inline data: <rf-social-proof><script type="application/json">{…}</script></rf-social-proof>
    // Renders with no fetch — works from file:// and lets a server embed the feed in the page.
    const inline = this.querySelector('script[type="application/json"]');
    if (inline) {
      try { this.#show(JSON.parse(inline.textContent)); }
      catch (err) { console.error("[rf-social-proof] Invalid inline JSON:", err); this.hidden = true; }
      return;
    }

    const endpoint = this.#attr("endpoint", DEFAULTS.endpoint);
    try {
      const res = await fetch(endpoint, { headers: { accept: "application/json" } });
      if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
      this.#show(await res.json());
    } catch (err) {
      // Match the website: render nothing rather than a broken section.
      console.error("[rf-social-proof] Could not load reviews:", err);
      this.hidden = true;
      this.dispatchEvent(new CustomEvent("rf-error", { detail: err, bubbles: true }));
    }
  }

  #card(r) {
    const name = r.consumer?.displayName ?? "";
    const img = (r.consumer?.links || []).find((l) => l.rel === "profile-image");
    // title and text are nullable — Trustpilot permits star-only reviews.
    const title = r.title || "Trustpilot Review";
    const text = r.text || "Visit the Trustpilot website to read this review.";
    const avatar = img
      ? `<img src="${esc(img.href)}" alt="${esc(name)} profile image" loading="lazy" referrerpolicy="no-referrer">`
      : `<div class="init">${esc(initials(name))}</div>`;

    return `<div class="slide"><article class="card">
      <div class="stars" aria-label="${r.stars} out of 5 stars">${STAR.repeat(r.stars)}</div>
      <div class="cbody">
        <div class="content">
          <h3 class="title">${esc(title)}</h3>
          <p class="text">${esc(text)}</p>
        </div>
        <div class="who">${avatar}<span class="name">${esc(name)}</span></div>
      </div>
    </article></div>`;
  }

  /* Seamless loop, the way Embla does it: clone the last K cards before
     the first and the first K after the last. Scrolling always moves in
     the pressed direction; once motion settles on a clone we jump
     instantly to its real twin, which is pixel-identical, so nothing is
     visible. K covers the widest viewport (~2.5 cards each side). */
  #track(reviews) {
    const cards = reviews.map((r) => this.#card(r));
    if (cards.length < 2) return cards.join("");
    const k = Math.min(3, cards.length);
    const clone = (h) => h.replace('<div class="slide">', '<div class="slide clone" aria-hidden="true">');
    return [...cards.slice(-k).map(clone), ...cards, ...cards.slice(0, k).map(clone)].join("");
  }

  #render(data) {
    // Precedence: host attribute > feed (CMS) > built-in default.
    const heading = this.#attr("heading", data.heading || DEFAULTS.heading);
    const body = this.#attr("body", data.body || DEFAULTS.body);
    const note = this.#attr("note", data.note || DEFAULTS.note);
    const ctaLabel = this.#attr("cta-label", DEFAULTS.ctaLabel);
    const ctaHref = this.#attr("cta-href", DEFAULTS.ctaHref);
    const ctaTarget = this.#attr("cta-target", DEFAULTS.ctaTarget);
    // A new tab must not get a handle back to the opener.
    const ctaRel = ctaTarget === "_blank" ? ` rel="noopener noreferrer"` : "";

    // Portraits come from the feed when present, so a CMS stays the source
    // of truth; the inlined copies are the fallback.
    const portraits = Array.isArray(data.profileImages) && data.profileImages.length === 3
      ? data.profileImages.map((p, i) => ({ src: p.src, alt: p.alt, cls: A.portraits[i].cls }))
      : A.portraits;

    const showImages = !this.hasAttribute("no-images");
    const compact = this.hasAttribute("compact");

    this.#root.innerHTML = `<style>${STYLES}</style>
      <section class="wrap" aria-labelledby="rf-title">
        ${showImages ? `<div class="portraits">${portraits.map(
          (p) => `<img class="${p.cls}" src="${esc(p.src)}" alt="${esc(p.alt)}">`).join("")}</div>` : ""}

        <div class="head">
          <h2 id="rf-title">${esc(heading)}</h2>
          <p>${esc(body)}</p>
        </div>

        <div class="rating">
          <img class="leaf" src="${A.leafL}" alt="" aria-hidden="true">
          <p class="score">${esc(data.trustScore)} <span>out of 5</span></p>
          <a href="${esc(data.profileUrl)}" target="_blank" rel="noopener noreferrer">
            <img class="tp" src="${A.tp}" alt="Trustpilot">
          </a>
          <img class="leaf" src="${A.leafR}" alt="" aria-hidden="true">
        </div>

        ${compact ? "" : `<div class="carousel">
          <div class="vp" tabindex="0" role="region" aria-label="Customer reviews">
            <div class="track">${this.#track(data.reviews)}</div>
          </div>
          <div class="ctrls">
            <button type="button" data-d="-1" aria-label="Previous review">${ARROW_L}</button>
            <button type="button" data-d="1" aria-label="Next review">${ARROW_R}</button>
          </div>
        </div>

        <p class="note">${esc(note)}</p>
        ${ctaLabel ? `<div class="cta"><a href="${esc(ctaHref)}" target="${esc(ctaTarget)}"${ctaRel}>${esc(ctaLabel)}</a></div>` : ""}`}
      </section>`;

    if (showImages) this.#wirePortraits();
    if (!compact) this.#wireCarousel();
  }

  /* Fan the portraits out once the section scrolls into view. */
  #wirePortraits() {
    const el = this.#root.querySelector(".portraits");
    if (!el) return;
    this.#io = new IntersectionObserver(
      (entries) => entries.forEach((e) => el.classList.toggle("open", e.isIntersecting)),
      { threshold: 0, rootMargin: "0px 0px -40% 0px" } // ≈ GSAP start: "top 40%"
    );
    this.#io.observe(this);
  }

  /* Native scroll-snap carousel with a seamless loop (see #track). The
     stagger offset of every slide, clones included, is recomputed from its
     distance to the centre. */
  #wireCarousel() {
    const vp = this.#root.querySelector(".vp");
    const all = [...this.#root.querySelectorAll(".slide")];
    const real = all.filter((s) => !s.classList.contains("clone"));
    const n = real.length;
    const k = all.indexOf(real[0]); // leading clones
    const N = all.length;
    const MAX_OFFSET_STEPS = 4;

    const centerOf = (s) => s.offsetLeft + s.offsetWidth / 2;
    const viewMid = () => vp.scrollLeft + vp.clientWidth / 2;

    const nearest = () => {
      const mid = viewMid();
      let best = 0, bestD = Infinity;
      all.forEach((s, i) => {
        const d = Math.abs(centerOf(s) - mid);
        if (d < bestD) { bestD = d; best = i; }
      });
      return best;
    };

    // Extended index -> the real slide it represents.
    const toReal = (i) => k + ((((i - k) % n) + n) % n);

    const scrollToIdx = (i, behavior = "smooth") => {
      const s = all[Math.max(0, Math.min(N - 1, i))];
      vp.scrollTo({ left: centerOf(s) - vp.clientWidth / 2, behavior });
    };

    const offsets = () => {
      const mid = viewMid();
      for (const s of all) {
        s.style.setProperty(
          "--o",
          Math.min(Math.round(Math.abs(centerOf(s) - mid) / s.offsetWidth), MAX_OFFSET_STEPS)
        );
      }
    };

    // When motion stops on a clone, relocate to its real twin. Same pixels,
    // so the jump is invisible.
    const settle = () => {
      const i = nearest();
      if (all[i].classList.contains("clone")) { scrollToIdx(toReal(i), "instant"); offsets(); }
    };

    for (const b of this.#root.querySelectorAll(".ctrls button")) {
      b.addEventListener("click", () => scrollToIdx(nearest() + Number(b.dataset.d)));
    }

    let settleTimer;
    vp.addEventListener("scroll", () => {
      requestAnimationFrame(offsets);
      clearTimeout(settleTimer);
      settleTimer = setTimeout(settle, 120); // fallback where scrollend is unsupported
    }, { passive: true });
    if ("onscrollend" in vp) vp.addEventListener("scrollend", settle);

    this.#ro = new ResizeObserver(offsets);
    this.#ro.observe(this);

    requestAnimationFrame(() => {
      scrollToIdx(k + Math.floor(n / 2), "instant");
      offsets();
    });
  }
}

if (!customElements.get("rf-social-proof")) {
  customElements.define("rf-social-proof", RfSocialProof);
}

// Exposed for programmatic use; loading as a classic <script> is enough.
if (typeof window !== "undefined") window.RfSocialProof = RfSocialProof;
